use vstd::prelude::*;

verus! {

spec fn clip_spec(arr: Seq<i8>, min_val: i8, max_val: i8) -> Seq<i8> {
    if min_val <= max_val {
        Seq::new((0..arr.len()).map(|i| {
            let x = arr.index(i);
            if x < min_val {
                min_val
            } else if x > max_val {
                max_val
            } else {
                x
            }
        }))
    } else {
        Seq::new((0..arr.len()).map(|_| max_val))
    }
}

fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8>
    ensures
        clip_spec(vec_to_seq(arr), min_val, max_val) == vec_to_seq(&result),
{
    let mut output: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < arr.len()
        invariant
            i <= arr.len(),
            vec_to_seq(&output) == clip_spec(vec_to_seq(arr)[0..i], min_val, max_val),
        decreases arr.len() - i,
    {
        let x = arr[i];
        if min_val <= max_val {
            if x < min_val {
                output.push(min_val);
            } else if x > max_val {
                output.push(max_val);
            } else {
                output.push(x);
            }
        } else {
            // min_val > max_val, always output max_val
            output.push(max_val);
        }
        i += 1;
    }
    output
}

}
